{
  "name": "Maintenance360",
  "description": "Sistema integrado de gestão de manutenção predial - Vibe Cod Edition.",
  "requestFramePermissions": []
}

import React from 'react';
import { useLocation, Link, Outlet } from 'react-router-dom';
import { LayoutDashboard, ClipboardList, Settings, LogOut, Bell, Menu, Hexagon, Moon, Sun, Users, CalendarDays, PaintBucket, ShoppingCart, RefreshCcw, Wifi, Zap } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { useData } from '../../context/DataContext';
import { useTheme } from '../../context/ThemeContext';

export const Layout = () => {
  const { user, logout } = useAuth();
  const { tasks, isLoading, refreshData, lastUpdated } = useData();
  const { theme, toggleTheme } = useTheme();
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = React.useState(false);

  // Simple logic to count active high-criticality tasks for notification
  const alertCount = tasks.filter(t => t.criticality === 'Alta' && t.situation !== 'Concluído').length;

  const isActive = (path: string) => location.pathname === path;

  const navItems = [
    { path: '/', label: 'Dashboard', icon: LayoutDashboard },
    { path: '/tasks', label: 'Tarefas', icon: ClipboardList },
    { path: '/visits', label: 'Visitas', icon: Users },
    { path: '/schedule', label: 'Cronograma', icon: CalendarDays },
    { path: '/painting', label: 'Pintura', icon: PaintBucket },
    { path: '/purchases', label: 'Compras', icon: ShoppingCart },
  ];

  if (user?.role === 'admin') {
    navItems.push({ path: '/settings', label: 'Configurações', icon: Settings });
  }

  const handleManualSync = async () => {
      await refreshData();
  };

  return (
    <div className="flex h-screen bg-slate-950 bg-grid-pattern text-slate-100 font-sans overflow-hidden transition-colors duration-200">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-slate-900/80 backdrop-blur-xl border-r border-white/5 transform transition-transform duration-200 ease-in-out ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:relative md:translate-x-0 flex flex-col`}>
        <div className="flex flex-col items-center justify-center h-24 border-b border-white/5 p-4 relative">
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-cyan-500 via-blue-500 to-purple-500"></div>
          <div className="flex items-center gap-2 mb-1">
             <div className="bg-gradient-to-br from-cyan-500 to-blue-600 p-1.5 rounded-lg shadow-lg shadow-blue-500/20">
                <Hexagon className="text-white fill-white/20" size={20} strokeWidth={2} />
             </div>
             <h1 className="text-xl font-bold text-white leading-tight font-display tracking-tight">
                M360
             </h1>
          </div>
          <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">Facility Management</p>
        </div>

        <nav className="p-4 space-y-1 flex-1">
          <div className="mb-6 px-4">
             <div className="flex items-center gap-3 p-3 bg-slate-800/50 rounded-xl border border-white/5">
                <img src={user?.avatar} alt="User" className="w-9 h-9 rounded-lg border border-white/10" />
                <div>
                   <p className="text-sm font-semibold text-white font-display">{user?.name}</p>
                   <div className="flex items-center gap-1.5">
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                        <p className="text-[10px] text-slate-400 uppercase tracking-wide">{user?.role === 'admin' ? 'Admin' : 'Operador'}</p>
                   </div>
                </div>
             </div>
          </div>

          <div className="space-y-1 overflow-y-auto max-h-[calc(100vh-300px)] custom-scrollbar">
            {navItems.map((item) => (
                <Link
                key={item.path}
                to={item.path}
                onClick={() => setIsMobileMenuOpen(false)}
                className={`flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-200 group relative overflow-hidden ${
                    isActive(item.path)
                    ? 'bg-gradient-to-r from-blue-600/20 to-cyan-600/20 text-cyan-400 border border-cyan-500/20'
                    : 'text-slate-400 hover:bg-slate-800/50 hover:text-slate-200'
                }`}
                >
                {isActive(item.path) && <div className="absolute left-0 top-0 bottom-0 w-1 bg-cyan-400 rounded-r-full"></div>}
                <item.icon size={20} className={isActive(item.path) ? 'text-cyan-400' : 'text-slate-500 group-hover:text-slate-300'} />
                <span className="font-medium font-display">{item.label}</span>
                </Link>
            ))}
          </div>
        </nav>

        <div className="p-4 border-t border-white/5">
          <button
            onClick={logout}
            className="flex items-center w-full gap-3 px-4 py-3 text-slate-500 hover:bg-red-500/10 hover:text-red-400 rounded-lg transition-colors border border-transparent hover:border-red-500/20"
          >
            <LogOut size={20} />
            <span className="font-medium">Encerrar Sessão</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden relative">
        {/* Header */}
        <header className="h-16 bg-slate-900/80 backdrop-blur-md border-b border-white/5 flex items-center justify-between px-6 md:justify-end shrink-0 z-20">
           <button 
             className="md:hidden text-slate-300 hover:text-white"
             onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
           >
             <Menu size={24} />
           </button>

           <div className="flex items-center gap-4">
             {/* Theme Toggle (Currently locked to dark aesthetic visually, but functional for future) */}
             <button 
                onClick={toggleTheme}
                className="p-2 rounded-full text-slate-500 hover:bg-slate-800 hover:text-slate-300 transition-colors hidden"
             >
                {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
             </button>

             <div className="relative cursor-pointer hover:bg-slate-800 p-2 rounded-full transition-colors group">
               <Bell size={20} className="text-slate-400 group-hover:text-cyan-400 transition-colors" />
               {alertCount > 0 && (
                 <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full animate-ping"></span>
               )}
               {alertCount > 0 && (
                 <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full"></span>
               )}
             </div>
           </div>
        </header>

        {/* Page Content */}
        <main className="flex-1 overflow-y-auto p-4 md:p-8 relative">
           <div className="max-w-7xl mx-auto">
             <Outlet />
           </div>
        </main>

        {/* Status Bar */}
        <div className="h-10 bg-slate-900 border-t border-white/5 flex items-center justify-between px-6 shrink-0 z-10 text-[10px] md:text-xs text-slate-500 font-mono">
            <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                    <Wifi size={12} className="text-emerald-500" />
                    <span className="text-emerald-500 font-medium">ONLINE</span>
                </div>
                <span className="hidden sm:inline-block opacity-50">|</span>
                <span className="hidden sm:inline-block text-slate-400">
                    SYNC: {lastUpdated.toLocaleTimeString()}
                </span>
            </div>

            <div className="flex items-center gap-4">
                <button 
                   onClick={handleManualSync}
                   disabled={isLoading}
                   className="flex items-center gap-2 hover:text-cyan-400 transition-colors disabled:opacity-50"
                >
                    <RefreshCcw size={12} className={isLoading ? 'animate-spin' : ''} />
                    {isLoading ? 'SYNCING...' : 'FORCE SYNC'}
                </button>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useData } from '../../context/DataContext';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, Legend
} from 'recharts';
import { AlertTriangle, CheckCircle2, Clock, ListFilter, CalendarDays, Users, PaintBucket, ShoppingCart, ArrowRight, Zap, TrendingUp } from 'lucide-react';
import { useTheme } from '../../context/ThemeContext';
import { Link } from 'react-router-dom';

// Neon Palette for Vibe Cod
const COLORS = ['#3b82f6', '#06b6d4', '#8b5cf6', '#10b981', '#f59e0b', '#ef4444'];

export const Dashboard = () => {
  const { tasks, settings, visits, schedule, paintingProjects, purchases } = useData();
  const { theme } = useTheme();

  // State for date filter: '30' | '7' | '1' | 'all'
  const [dateRange, setDateRange] = useState('30');

  // --- Filter Logic ---
  const filteredTasks = useMemo(() => {
    if (dateRange === 'all') return tasks;

    const now = new Date();
    // Reset time to start of day for accurate comparison
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    return tasks.filter(task => {
        if (!task.callDate) return false;

        let taskDate = new Date(task.callDate);
        if (isNaN(taskDate.getTime())) {
             if (task.callDate.includes('/')) {
                 const [d, m, y] = task.callDate.split('/');
                 taskDate = new Date(Number(y), Number(m) - 1, Number(d));
             } else {
                 return false;
             }
        }
        taskDate.setHours(0, 0, 0, 0);

        if (dateRange === '1') {
            return taskDate.getTime() === today.getTime();
        } else if (dateRange === '7') {
            const startOfWeek = new Date(today);
            startOfWeek.setDate(today.getDate() - today.getDay());
            return taskDate >= startOfWeek;
        } else if (dateRange === '30') {
            const thirtyDaysAgo = new Date(today);
            thirtyDaysAgo.setDate(today.getDate() - 30);
            return taskDate >= thirtyDaysAgo;
        }
        return true;
    });
  }, [tasks, dateRange]);

  // --- Metrics Calculation ---
  const totalTasks = filteredTasks.length;
  const inProgressTasks = filteredTasks.filter(t => t.situation === 'Em Andamento').length;
  const completedTasks = filteredTasks.filter(t => t.situation === 'Concluído').length;
  const highCritTasks = filteredTasks.filter(t => t.criticality === 'Alta' && t.situation !== 'Concluído').length;

  const situationData = settings.situations.map(sit => ({
      name: sit.name,
      value: filteredTasks.filter(t => t.situation === sit.name).length
  })).filter(item => item.value > 0); 

  const knownSituations = settings.situations.map(s => s.name);
  const unknownTasksCount = filteredTasks.filter(t => !knownSituations.includes(t.situation)).length;
  if (unknownTasksCount > 0) {
      situationData.push({ name: 'Outros', value: unknownTasksCount });
  }

  const sectorData = settings.sectors.map(sector => ({
    name: sector.name,
    tarefas: filteredTasks.filter(t => t.sectorId === sector.id).length
  })).filter(d => d.tarefas > 0);

  // --- Helper Logic for Bottom Section ---
  const days = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
  const dayKey = days[new Date().getDay()];
  const todaySchedule = schedule.map(item => ({
      shift: item.shift,
      task: (item as any)[dayKey] || '-' 
  })).filter(i => i.task !== '-' && i.task !== '');

  const recentVisits = [...visits].reverse().slice(0, 3);
  const activePainting = paintingProjects.slice(0, 3);
  const pendingPurchases = purchases.filter(p => !p.approvalDate).slice(0, 3);

  const StatCard = ({ title, value, icon: Icon, colorClass, gradient, subText }: any) => (
    <div className="bg-slate-900/60 backdrop-blur-md p-6 rounded-2xl border border-white/5 hover:border-white/10 transition-all group relative overflow-hidden">
      <div className={`absolute top-0 right-0 w-24 h-24 bg-gradient-to-br ${gradient} opacity-10 rounded-bl-full group-hover:opacity-20 transition-opacity`}></div>
      <div className="flex items-start justify-between relative z-10">
        <div>
          <p className="text-sm font-medium text-slate-400 mb-1">{title}</p>
          <h3 className="text-3xl font-bold text-white font-display tracking-tight">{value}</h3>
          {subText && <p className="text-xs text-slate-500 mt-2 flex items-center gap-1"><TrendingUp size={10}/> {subText}</p>}
        </div>
        <div className={`p-3 rounded-xl bg-slate-800/80 border border-white/5 group-hover:scale-110 transition-transform ${colorClass}`}>
          <Icon size={24} className="text-white" />
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-fade-in pb-10">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h2 className="text-3xl font-bold text-white font-display">Dashboard</h2>
           <p className="text-slate-400 flex items-center gap-2 text-sm"><Zap size={14} className="text-yellow-500"/> Visão geral em tempo real</p>
        </div>
        <div className="flex gap-2">
           <select 
             value={dateRange}
             onChange={(e) => setDateRange(e.target.value)}
             className="bg-slate-900 border border-slate-700 text-slate-300 rounded-xl px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/50 hover:bg-slate-800 transition-colors cursor-pointer"
           >
             <option value="30">Últimos 30 dias</option>
             <option value="7">Esta semana</option>
             <option value="1">Hoje</option>
             <option value="all">Todo o período</option>
           </select>
        </div>
      </div>

      {/* Top KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Total de Tarefas" 
          value={totalTasks} 
          icon={ListFilter} 
          colorClass="text-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.3)]"
          gradient="from-blue-600 to-cyan-500"
          subText={dateRange === 'all' ? 'Histórico completo' : 'No período'}
        />
        <StatCard 
          title="Em Andamento" 
          value={inProgressTasks} 
          icon={Clock} 
          colorClass="text-cyan-400 shadow-[0_0_15px_rgba(6,182,212,0.3)]"
          gradient="from-cyan-500 to-emerald-500"
          subText="Atividades ativas"
        />
        <StatCard 
          title="Concluídas" 
          value={completedTasks} 
          icon={CheckCircle2} 
          colorClass="text-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.3)]" 
          gradient="from-emerald-500 to-teal-500"
          subText="Finalizadas"
        />
        <StatCard 
          title="Criticidade Alta" 
          value={highCritTasks} 
          icon={AlertTriangle} 
          colorClass="text-red-400 shadow-[0_0_15px_rgba(239,68,68,0.3)]" 
          gradient="from-red-500 to-orange-500"
          subText="Atenção requerida"
        />
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Situation Distribution */}
        <div className="bg-slate-900/60 backdrop-blur-md p-6 rounded-2xl border border-white/5">
          <h3 className="text-lg font-bold text-white mb-6 font-display">Status das Tarefas</h3>
          <div className="h-64 w-full">
            {situationData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                    <Pie
                    data={situationData}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={80}
                    paddingAngle={5}
                    dataKey="value"
                    stroke="#0f172a"
                    strokeWidth={2}
                    >
                    {situationData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                    </Pie>
                    <Tooltip 
                    contentStyle={{ backgroundColor: '#0f172a', borderRadius: '12px', border: '1px solid #1e293b', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.5)', color: '#f8fafc' }}
                    itemStyle={{ color: '#cbd5e1' }}
                    />
                    <Legend verticalAlign="bottom" height={36} iconType="circle" />
                </PieChart>
                </ResponsiveContainer>
            ) : (
                <div className="h-full flex items-center justify-center text-slate-500 text-sm">
                    Sem dados para o período.
                </div>
            )}
          </div>
        </div>

        {/* Tasks by Sector */}
        <div className="bg-slate-900/60 backdrop-blur-md p-6 rounded-2xl border border-white/5">
          <h3 className="text-lg font-bold text-white mb-6 font-display">Tarefas por Setor</h3>
          <div className="h-64 w-full">
            {sectorData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                <BarChart data={sectorData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                    <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} />
                    <Tooltip 
                     cursor={{fill: '#1e293b'}}
                     contentStyle={{ backgroundColor: '#0f172a', borderRadius: '12px', border: '1px solid #1e293b', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.5)', color: '#f8fafc' }}
                     itemStyle={{ color: '#60a5fa' }}
                    />
                    <Bar dataKey="tarefas" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={40}>
                         {sectorData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                        ))}
                    </Bar>
                </BarChart>
                </ResponsiveContainer>
            ) : (
                <div className="h-full flex items-center justify-center text-slate-500 text-sm">
                    Sem dados para o período.
                </div>
            )}
          </div>
        </div>
      </div>

      {/* --- OPERATIONAL SUMMARY SECTION --- */}
      <div>
        <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2 font-display">
            Resumo Operacional
            <div className="h-px bg-slate-800 flex-1 ml-4"></div>
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">

            {/* Card: Visitas Recentes */}
            <div className="bg-slate-900/40 backdrop-blur-sm p-5 rounded-2xl border border-white/5 flex flex-col hover:border-blue-500/30 transition-colors">
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2 text-slate-200 font-semibold font-display">
                        <Users size={18} className="text-blue-500" />
                        <h4>Visitas Recentes</h4>
                    </div>
                    <Link to="/visits" className="text-xs text-blue-400 hover:text-blue-300 flex items-center gap-1 transition-colors">Ver tudo <ArrowRight size={12}/></Link>
                </div>
                <div className="space-y-3 flex-1">
                    {recentVisits.length === 0 ? (
                        <p className="text-sm text-slate-500 italic">Nenhuma visita recente.</p>
                    ) : (
                        recentVisits.map(v => (
                            <div key={v.id} className="flex items-center justify-between text-sm p-3 bg-slate-800/50 rounded-xl border border-white/5">
                                <div>
                                    <p className="font-bold text-slate-200">{v.unit} - {v.tower}</p>
                                    <p className="text-xs text-slate-400">{v.situation}</p>
                                </div>
                                <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold border ${v.status === 'Pendente' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' : 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20'}`}>
                                    {v.status}
                                </span>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Card: Cronograma Hoje */}
            <div className="bg-slate-900/40 backdrop-blur-sm p-5 rounded-2xl border border-white/5 flex flex-col hover:border-emerald-500/30 transition-colors">
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2 text-slate-200 font-semibold font-display">
                        <CalendarDays size={18} className="text-emerald-500" />
                        <h4>Agenda de Hoje</h4>
                    </div>
                    <Link to="/schedule" className="text-xs text-emerald-400 hover:text-emerald-300 flex items-center gap-1 transition-colors">Ver tudo <ArrowRight size={12}/></Link>
                </div>
                <div className="space-y-3 flex-1">
                    {todaySchedule.length === 0 ? (
                         <p className="text-sm text-slate-500 italic">Sem atividades agendadas.</p>
                    ) : (
                        todaySchedule.map((s, idx) => (
                            <div key={idx} className="flex items-start gap-3 text-sm p-3 bg-slate-800/50 rounded-xl border-l-2 border-emerald-500 border-t border-r border-b border-t-white/5 border-r-white/5 border-b-white/5">
                                <div className="flex-1">
                                    <p className="font-bold text-emerald-400 uppercase text-[10px] mb-0.5 tracking-wider">{s.shift}</p>
                                    <p className="text-slate-300 line-clamp-2">{s.task}</p>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Card: Pintura em Andamento */}
            <div className="bg-slate-900/40 backdrop-blur-sm p-5 rounded-2xl border border-white/5 flex flex-col hover:border-indigo-500/30 transition-colors">
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2 text-slate-200 font-semibold font-display">
                        <PaintBucket size={18} className="text-indigo-500" />
                        <h4>Pintura</h4>
                    </div>
                    <Link to="/painting" className="text-xs text-indigo-400 hover:text-indigo-300 flex items-center gap-1 transition-colors">Ver tudo <ArrowRight size={12}/></Link>
                </div>
                <div className="space-y-3 flex-1">
                    {activePainting.length === 0 ? (
                        <p className="text-sm text-slate-500 italic">Nenhum projeto de pintura.</p>
                    ) : (
                        activePainting.map(p => (
                            <div key={p.id} className="text-sm p-3 bg-slate-800/50 rounded-xl border border-white/5">
                                <div className="flex justify-between items-start mb-1">
                                    <span className="font-medium text-slate-200">{p.local}</span>
                                    <span className={`text-[10px] px-1.5 rounded border ${p.criticality === 'Alta' ? 'bg-red-500/10 text-red-400 border-red-500/20' : 'bg-slate-700 text-slate-400 border-slate-600'}`}>{p.criticality}</span>
                                </div>
                                <p className="text-xs text-slate-500">{p.tower}</p>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Card: Compras Pendentes */}
            <div className="bg-slate-900/40 backdrop-blur-sm p-5 rounded-2xl border border-white/5 flex flex-col hover:border-orange-500/30 transition-colors">
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2 text-slate-200 font-semibold font-display">
                        <ShoppingCart size={18} className="text-orange-500" />
                        <h4>Solicitações</h4>
                    </div>
                    <Link to="/purchases" className="text-xs text-orange-400 hover:text-orange-300 flex items-center gap-1 transition-colors">Ver tudo <ArrowRight size={12}/></Link>
                </div>
                <div className="space-y-3 flex-1">
                     {pendingPurchases.length === 0 ? (
                        <div className="h-full flex items-center justify-center text-center">
                            <p className="text-xs text-slate-500 bg-slate-800/50 py-2 px-4 rounded-full border border-white/5">Tudo em dia!</p>
                        </div>
                    ) : (
                        pendingPurchases.map(req => (
                            <div key={req.id} className="flex items-center justify-between text-sm p-3 bg-slate-800/50 rounded-xl border border-white/5">
                                <div>
                                    <div className="flex items-center gap-2">
                                        <span className="font-bold text-white bg-orange-500/20 px-1.5 rounded text-xs text-orange-400">{req.quantity}x</span>
                                        <span className="text-slate-300 truncate max-w-[100px]">{req.description}</span>
                                    </div>
                                    <p className="text-[10px] text-slate-500 uppercase mt-0.5">{req.local}</p>
                                </div>
                                <div className="text-right">
                                    <p className="text-[10px] font-bold text-orange-400">PENDENTE</p>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

        </div>
      </div>
    </div>
  );
};

import React, { createContext, useContext, useState, ReactNode } from 'react';
import { User, Role } from '../types';

interface AuthContextType {
  user: User | null;
  login: (role: Role) => void;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children?: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null);

  const login = (role: Role) => {
    // Simulate login
    // Using Deep Blue/Purple for admin
    setUser({
      id: 'u1',
      name: role === 'admin' ? 'SysAdmin' : 'Field Operator 01',
      email: role === 'admin' ? 'admin@m360.com' : 'op@m360.com',
      role: role,
      avatar: `https://ui-avatars.com/api/?name=${role}&background=3b82f6&color=fff&rounded=true`,
    });
  };

  const logout = () => {
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

