                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-emerald-600 dark:text-emerald-500">In:</span> 
                                        {formatShortDate(task.startDate)}
                                    </div>
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
