// Neon Palette for Vibe Cod
const COLORS = ['#3b82f6', '#06b6d4', '#8b5cf6', '#10b981', '#f59e0b', '#ef4444'];

export const Dashboard = () => {
  const { tasks, settings, visits, schedule, paintingProjects, purchases } = useData();
  const { theme } = useTheme();

  // Alterado: Padrão 'all' para garantir que dados importados antigos apareçam
  const [dateRange, setDateRange] = useState('all');

  // Helper robusto para datas
  const parseDate = (dateStr: string) => {
      if (!dateStr) return null;

      // Tenta ISO (YYYY-MM-DD)
      let d = new Date(dateStr);
      if (!isNaN(d.getTime())) return d;

      // Tenta PT-BR (DD/MM/YYYY)
      if (dateStr.includes('/')) {
          const parts = dateStr.split('/');
          if (parts.length === 3) {
              // Ajusta ano de 2 digitos se necessário
              let year = parseInt(parts[2]);
              if (year < 100) year += 2000;

              d = new Date(year, parseInt(parts[1]) - 1, parseInt(parts[0]));
              if (!isNaN(d.getTime())) return d;
          }
      }
      return null;
  };

  // --- Filter Logic ---
  const filteredTasks = useMemo(() => {
    // Se o filtro for 'all', retorna tudo independente da data estar certa ou errada
    if (dateRange === 'all') return tasks;

    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    return tasks.filter(task => {
        const taskDate = parseDate(task.callDate);

        // Se a data for inválida mas o filtro não é 'all', infelizmente escondemos ou mostramos?
        // Vamos esconder apenas se tivermos certeza que não bate.
        if (!taskDate) return false; 

        taskDate.setHours(0, 0, 0, 0);

        if (dateRange === '1') {
            return taskDate.getTime() === today.getTime();
        } else if (dateRange === '7') {
            const startOfWeek = new Date(today);
            startOfWeek.setDate(today.getDate() - today.getDay());
            return taskDate >= startOfWeek;
        } else if (dateRange === '30') {
            const thirtyDaysAgo = new Date(today);
            thirtyDaysAgo.setDate(today.getDate() - 30);
            return taskDate >= thirtyDaysAgo;
        }
        return true;
    });
  }, [tasks, dateRange]);

  // --- Metrics Calculation (Case Insensitive) ---
  const totalTasks = filteredTasks.length;

  const inProgressTasks = filteredTasks.filter(t => 
    (t.situation || '').toLowerCase().includes('andamento')
  ).length;

  const completedTasks = filteredTasks.filter(t => 
    (t.situation || '').toLowerCase().includes('conclu')
  ).length;

  const highCritTasks = filteredTasks.filter(t => {
      const crit = (t.criticality || '').toLowerCase();
      const sit = (t.situation || '').toLowerCase();
      return (crit.includes('alt') || crit.includes('high')) && !sit.includes('conclu');
  }).length;

  // Group situations for Chart (Aggressive Normalization)
  const situationMap = new Map<string, number>();
  filteredTasks.forEach(t => {
      let rawSit = (t.situation || 'Aberto').trim();
      let lowerSit = rawSit.toLowerCase();
      let displaySit = rawSit;

      // Normalização forçada para agrupar no gráfico
      if (lowerSit.includes('andamento')) displaySit = 'Em Andamento';
      else if (lowerSit.includes('conclu')) displaySit = 'Concluído';
      else if (lowerSit.includes('cancel')) displaySit = 'Cancelado';
      else if (lowerSit.includes('aberto')) displaySit = 'Aberto';
      else {
          // Capitalize
          displaySit = displaySit.charAt(0).toUpperCase() + displaySit.slice(1).toLowerCase();
      }

      situationMap.set(displaySit, (situationMap.get(displaySit) || 0) + 1);
  });

  const situationData = Array.from(situationMap.entries())
    .map(([name, value]) => ({ name, value }))
