                            </td>

                            {/* Criticality */}
                            <td className="px-3 py-3 text-center align-top">
                                <span className={`inline-block px-2.5 py-1 rounded-md text-[10px] font-bold border uppercase tracking-wider ${getCriticalityColor(task.criticality)}`}>
                                    {task.criticality}
