                        <select name="criticality" value={formData.criticality} onChange={handleChange} className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 outline-none">
                           <option value="Baixa">Baixa</option>
                           <option value="Média">Média</option>
                           <option value="Alta">Alta</option>
                        </select>
                    </div>
                </div>
             </div>

             {/* Materials */}
             <div className="border-t border-slate-100 dark:border-slate-700 pt-6">
                <h4 className="text-sm uppercase tracking-wide text-slate-500 dark:text-slate-400 font-semibold mb-4">Materiais Disponíveis</h4>
                <div className="flex flex-col gap-3">
                   {settings.materials.map(mat => {
                       const isChecked = formData.materials?.includes(mat.id);
                       return (
                           <div key={mat.id} 
                                onClick={() => handleMaterialToggle(mat.id)}
                                className={`flex items-center justify-between p-3 rounded-lg border cursor-pointer transition-all ${
                                    isChecked 
                                    ? 'bg-blue-50 dark:bg-blue-900/30 border-blue-500 dark:border-blue-700 shadow-sm' 
                                    : 'bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800'
                                }`}
                           >
                              <div className="flex items-center gap-3">
                                  <div className={`w-5 h-5 rounded flex items-center justify-center border transition-colors ${isChecked ? 'bg-blue-500 border-blue-500' : 'bg-white dark:bg-slate-800 border-slate-300 dark:border-slate-600'}`}>
                                      {isChecked && <CheckSquare size={14} className="text-white" />}
                                  </div>
                                  <span className={`text-sm font-medium ${isChecked ? 'text-blue-900 dark:text-blue-200' : 'text-slate-600 dark:text-slate-400'}`}>{mat.name}</span>
                              </div>
                              <div className="flex items-center gap-2">
                                  <span className={`text-xs font-bold px-2 py-1 rounded uppercase tracking-wider ${isChecked ? 'bg-blue-200 text-blue-800 dark:bg-blue-900 dark:text-blue-200' : 'bg-slate-100 text-slate-400 dark:bg-slate-800 dark:text-slate-500'}`}>
                                      {isChecked ? 'SIM' : 'NÃO'}
                                  </span>
                              </div>
                           </div>
                       );
                   })}
                </div>
             </div>

             {/* Dates */}
             <div className="border-t border-slate-100 dark:border-slate-700 pt-6">
                <h4 className="text-sm uppercase tracking-wide text-slate-500 dark:text-slate-400 font-semibold mb-4">Agendamento</h4>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Data Chamado</label>
                        <div className="relative">
                            <Calendar size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                            <input type="date" name="callDate" value={formData.callDate} onChange={handleChange} className="w-full pl-10 pr-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                        </div>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Data Início</label>
                        <input type="date" name="startDate" value={formData.startDate} onChange={handleChange} className="w-full px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Data Término</label>
                        <input type="date" name="endDate" value={formData.endDate} onChange={handleChange} className="w-full px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
                    </div>
                </div>
             </div>
          </form>

          {/* Footer Actions */}
          <div className="sticky bottom-0 bg-white dark:bg-slate-800 border-t border-slate-100 dark:border-slate-700 p-6 flex items-center justify-end gap-3 rounded-b-2xl">
              <button 
                type="button"
                onClick={onClose}
                className="px-6 py-2.5 text-slate-600 dark:text-slate-400 font-medium hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg transition-colors"
              >
                  Cancelar
              </button>
              <button 
                onClick={handleSubmit}
                className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg shadow-lg shadow-blue-200 dark:shadow-none transition-transform active:scale-95"
              >
                  <Save size={18} />
                  Salvar Tarefa
              </button>
          </div>
       </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { useAuth } from '../../context/AuthContext';
import { Plus, Search, Filter, Download, Edit2, Trash2, Wrench, Upload, Eraser, Calendar } from 'lucide-react';
import { TaskFormModal } from '../ui/TaskFormModal';
import { Task } from '../../types';

export const TaskList = () => {
  const { tasks, settings, deleteTask, exportTasksToCSV, importDataFromCSV } = useData();
  const { user } = useAuth();
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Filter States
  const [searchTerm, setSearchTerm] = useState('');
  const [filterSituation, setFilterSituation] = useState('Todos');
  const [dateFilter, setDateFilter] = useState<'all' | 'week' | 'month'>('all');

  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  // Helper para buscar nomes (com fallback caso o ID seja o próprio nome importado)
  const findName = (list: any[], id: string, defaultLabel: string) => {
      const found = list.find(i => i.id === id);
      return found ? found.name : (id || defaultLabel);
  };

  const getResponsibleName = (id: string) => findName(settings.responsibles, id, 'N/A');
  const getSectorName = (id: string) => findName(settings.sectors, id, 'N/A');
  const getServiceName = (id: string) => findName(settings.services, id, 'Serviço');
  const getTowerName = (id: string) => findName(settings.towers, id, 'Torre');

  const getMaterialNames = (ids: string[]) => {
      if (!ids || ids.length === 0) return null;
      return ids.map(id => settings.materials.find(m => m.id === id)?.name || id).filter(Boolean).join(', ');
  };

  const handleEdit = (task: Task) => {
    setEditingTask(task);
    setIsModalOpen(true);
  };

  const handleAddNew = () => {
    setEditingTask(undefined);
    setIsModalOpen(true);
  };

  const handleClearFilters = () => {
      setSearchTerm('');
      setFilterSituation('Todos');
      setDateFilter('all');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = async (event) => {
          const content = event.target?.result as string;
          const result = await importDataFromCSV(content);
          alert(`${result.message}\n${result.count ? `Importados: ${result.count} registros.` : ''}`);
          e.target.value = ''; 
      };
      reader.readAsText(file);
  };

  // Helper de Data Segura
  const parseTaskDate = (dateString: string) => {
      if (!dateString) return new Date(0); // Data muito antiga
      // Tenta ISO
      let d = new Date(dateString);
      if (!isNaN(d.getTime())) return d;

      // Tenta BR (DD/MM/YYYY)
      if (dateString.includes('/')) {
          const [day, month, year] = dateString.split('/');
          d = new Date(Number(year), Number(month) - 1, Number(day));
          if (!isNaN(d.getTime())) return d;
      }
      return new Date(0);
  };

  const filteredTasks = tasks.filter(task => {
    const term = searchTerm.toLowerCase().trim();

    // 1. Search Filter (Robust)
    const serviceName = getServiceName(task.serviceId).toLowerCase();
    const towerName = getTowerName(task.towerId).toLowerCase();
    const title = (task.title || '').toLowerCase();
    const location = (task.location || '').toLowerCase();
    const responsible = getResponsibleName(task.responsibleId).toLowerCase();

    const matchesSearch = term === '' || 
                          title.includes(term) || 
                          location.includes(term) ||
                          serviceName.includes(term) ||
                          towerName.includes(term) ||
                          responsible.includes(term);

    // 2. Situation Filter (Normalization: "Em Andamento" == "EM ANDAMENTO")
    const taskSit = (task.situation || '').toLowerCase().trim();
    const filterSit = filterSituation.toLowerCase().trim();
    const matchesSituation = filterSituation === 'Todos' || taskSit === filterSit;

    // 3. Date Filter (Based on Call Date)
    let matchesDate = true;
    if (dateFilter !== 'all') {
        const taskDate = parseTaskDate(task.callDate);
        taskDate.setHours(0,0,0,0);

        const now = new Date();
        now.setHours(0,0,0,0);

        if (dateFilter === 'month') {
            matchesDate = taskDate.getMonth() === now.getMonth() && taskDate.getFullYear() === now.getFullYear();
        } else if (dateFilter === 'week') {
            const startOfWeek = new Date(now);
            startOfWeek.setDate(now.getDate() - now.getDay()); // Sunday

            const endOfWeek = new Date(startOfWeek);
            endOfWeek.setDate(startOfWeek.getDate() + 6); // Saturday

            matchesDate = taskDate >= startOfWeek && taskDate <= endOfWeek;
        }
    }

    return matchesSearch && matchesSituation && matchesDate;
  });

  // Robust Status Coloring (Case Insensitive)
  const getStatusColor = (status: string) => {
    const s = status?.toLowerCase() || '';
    if (s.includes('conclu')) return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300 border-blue-200 dark:border-blue-800';
    if (s.includes('andamento') || s.includes('execu')) return 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/30 dark:text-cyan-300 border-cyan-200 dark:border-cyan-800';
    if (s.includes('cancel')) return 'bg-slate-100 text-slate-600 dark:bg-slate-700 dark:text-slate-300 border-slate-200 dark:border-slate-600';
    return 'bg-indigo-50 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-300 border-indigo-200 dark:border-indigo-800'; // Aberto/Outros
  };

  // Robust Criticality Coloring
  const getCriticalityColor = (crit: string) => {
    const c = crit?.toLowerCase() || '';
    if (c.includes('alt') || c.includes('high') || c.includes('urge') || c.includes('crit')) return 'text-red-600 bg-red-50 border-red-200 dark:bg-red-900/20 dark:text-red-400 dark:border-red-900/50 shadow-[0_0_10px_rgba(239,68,68,0.1)]';
    if (c.includes('méd') || c.includes('med')) return 'text-amber-600 bg-amber-50 border-amber-200 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-900/50';
    return 'text-emerald-600 bg-emerald-50 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-900/50'; // Baixa/Low
  };

  // Maintenance Type Color
  const getTypeColor = (type?: string) => {
      switch(type) {
          case 'Corretiva': return 'bg-red-50 text-red-600 border-red-100 dark:bg-red-900/20 dark:border-red-900/30 dark:text-red-300';
          case 'Preventiva': return 'bg-blue-50 text-blue-600 border-blue-100 dark:bg-blue-900/20 dark:border-blue-900/30 dark:text-blue-300';
          case 'Programada': return 'bg-purple-50 text-purple-600 border-purple-100 dark:bg-purple-900/20 dark:border-purple-900/30 dark:text-purple-300';
          default: return 'bg-slate-50 text-slate-500';
      }
  };

  // Short Date Formatter (DD/MM)
  const formatShortDate = (dateString?: string) => {
      if (!dateString || dateString.trim() === '') return '-';
      const d = parseTaskDate(dateString);
      if (d.getTime() === 0) return dateString.substring(0, 5); // Fallback to string chop if parse fails completely
      return d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });
  };

  const hasActiveFilters = searchTerm !== '' || filterSituation !== 'Todos' || dateFilter !== 'all';

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Tarefas de Manutenção</h2>
          <p className="text-slate-500 dark:text-slate-400">Gerencie todas as ordens de serviço</p>
        </div>
        <div className="flex gap-2">
           <label className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors cursor-pointer">
              <Upload size={18} />
              <span className="hidden sm:inline">Importar</span>
              <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
           </label>
           <button onClick={exportTasksToCSV} className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
              <Download size={18} />
              <span className="hidden sm:inline">Exportar</span>
           </button>
           <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm shadow-blue-200 dark:shadow-none transition-all transform active:scale-95">
              <Plus size={18} />
              <span>Nova Tarefa</span>
           </button>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col xl:flex-row gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
         <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Buscar por serviço, torre, local, responsável..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm text-slate-800 dark:text-slate-200 placeholder-slate-400"
            />
         </div>
         <div className="flex flex-wrap items-center gap-2">

            {/* Situation Filter */}
            <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-900 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700">
                <Filter size={16} className="text-slate-400" />
                <select 
                value={filterSituation}
                onChange={(e) => setFilterSituation(e.target.value)}
                className="bg-transparent text-sm text-slate-600 dark:text-slate-300 focus:outline-none"
                >
                <option value="Todos">Todas as Situações</option>
                {settings.situations.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                </select>
            </div>

            {/* Date Filter */}
            <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-900 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700">
                <Calendar size={16} className="text-slate-400" />
                <select 
                value={dateFilter}
                onChange={(e) => setDateFilter(e.target.value as any)}
                className="bg-transparent text-sm text-slate-600 dark:text-slate-300 focus:outline-none"
                >
                <option value="all">Todo o Período</option>
                <option value="week">Esta Semana</option>
                <option value="month">Este Mês</option>
                </select>
            </div>

            {/* Clear Button (Top) */}
            {hasActiveFilters && (
                <button 
                    onClick={handleClearFilters}
                    className="flex items-center gap-2 px-3 py-2 text-sm text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors border border-transparent hover:border-red-100"
                >
                    <Eraser size={16} />
                    Limpar
                </button>
            )}
         </div>
      </div>

      {/* Table Container */}
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden flex flex-col">
         <div className="overflow-x-auto">
           <table className="w-full text-left border-collapse min-w-[1000px]">
             <thead>
               <tr className="bg-slate-50 dark:bg-slate-700/50 border-b border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 text-xs uppercase font-semibold">
                 <th className="px-3 py-3 w-[25%]">Serviço / Torre / Tipo</th>
                 <th className="px-3 py-3 w-[15%]">Datas (Ab/In/Fi)</th>
                 <th className="px-3 py-3 w-[15%]">Local / Setor</th>
                 <th className="px-3 py-3">Responsável</th>
                 <th className="px-3 py-3 text-center">Mat.</th>
                 <th className="px-3 py-3 text-center">Situação</th>
                 <th className="px-3 py-3 text-center">Crit.</th>
                 <th className="px-3 py-3 text-right">Ações</th>
               </tr>
             </thead>
             <tbody className="text-sm divide-y divide-slate-100 dark:divide-slate-700">
                {filteredTasks.length === 0 ? (
                  <tr>
                    <td colSpan={8} className="px-4 py-8 text-center text-slate-400 dark:text-slate-500">
                       Nenhuma tarefa encontrada.
                    </td>
                  </tr>
                ) : (
                  filteredTasks.map((task) => {
                      const materialNames = getMaterialNames(task.materials);
                      return (
                        <tr key={task.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                            {/* Service / Tower / Type */}
                            <td className="px-3 py-3 align-top">
                                <div className="font-bold text-slate-800 dark:text-slate-200 flex items-start gap-2 text-sm">
                                    <Wrench size={14} className="text-blue-500 shrink-0 mt-0.5" />
                                    <span className="leading-tight">{getServiceName(task.serviceId)}</span>
                                </div>
                                <div className="flex items-center gap-2 mt-1 pl-6">
                                    <span className="text-xs font-semibold text-blue-600 dark:text-blue-400">
                                        {getTowerName(task.towerId)}
                                    </span>
                                    <span className={`text-[9px] px-1.5 py-0.5 rounded border uppercase tracking-wider ${getTypeColor(task.type)}`}>
                                        {task.type || 'Corretiva'}
                                    </span>
                                </div>
                            </td>

                            {/* Consolidated Dates */}
                            <td className="px-3 py-3 align-top">
                                <div className="flex flex-col gap-0.5 text-xs font-mono">
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-slate-400">Ab:</span> 
                                        {formatShortDate(task.callDate)}
                                    </div>
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-emerald-600 dark:text-emerald-500">In:</span> 
                                        {formatShortDate(task.startDate)}
                                    </div>
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-indigo-500">Fi:</span> 
                                        {formatShortDate(task.endDate)}
                                    </div>
                                </div>
                            </td>

                            {/* Location / Sector */}
                            <td className="px-3 py-3 align-top">
                                <div className="text-slate-700 dark:text-slate-300 font-medium text-sm leading-tight truncate max-w-[150px]" title={task.location}>
                                    {task.location}
                                </div>
                                <div className="text-xs text-slate-400 dark:text-slate-500 mt-0.5">
                                    {getSectorName(task.sectorId)}
                                </div>
                            </td>

                            {/* Responsible */}
                            <td className="px-3 py-3 align-top text-slate-600 dark:text-slate-400 text-xs">
                                <div className="truncate max-w-[120px]" title={getResponsibleName(task.responsibleId)}>
                                    {getResponsibleName(task.responsibleId)}
                                </div>
                            </td>

                            {/* Materials */}
                            <td className="px-3 py-3 text-center align-top">
                                {materialNames ? (
                                    <div className="group relative cursor-help flex justify-center">
                                        <span className="w-5 h-5 flex items-center justify-center rounded bg-emerald-100 text-emerald-700 text-[10px] font-bold">
                                            Sim
                                        </span>
                                        <div className="absolute hidden group-hover:block right-0 top-full mt-1 bg-slate-800 text-white text-[10px] p-2 rounded shadow-lg z-10 w-32 text-left">
                                            {materialNames}
                                        </div>
                                    </div>
                                ) : (
                                    <span className="text-slate-300 dark:text-slate-600 text-lg leading-none">-</span>
                                )}
                            </td>

                            {/* Situation */}
                            <td className="px-3 py-3 text-center align-top">
                                <span className={`inline-block px-2.5 py-1 rounded-full text-[10px] font-bold border uppercase tracking-wider ${getStatusColor(task.situation)}`}>
                                    {task.situation}
                                </span>
                            </td>

                            {/* Criticality */}
                            <td className="px-3 py-3 text-center align-top">
                                <span className={`inline-block px-2.5 py-1 rounded-md text-[10px] font-bold border uppercase tracking-wider ${getCriticalityColor(task.criticality)}`}>
                                    {task.criticality}
                                </span>
                            </td>

                            {/* Actions */}
                            <td className="px-3 py-3 text-right align-top">
                                <div className="flex items-center justify-end gap-1">
                                    <button onClick={() => handleEdit(task)} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded transition-colors" title="Editar">
                                    <Edit2 size={16} />
                                    </button>
                                    {user?.role === 'admin' && (
                                    <button onClick={() => deleteTask(task.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded transition-colors" title="Excluir">
                                        <Trash2 size={16} />
                                    </button>
                                    )}
                                </div>
                            </td>
                        </tr>
                      );
                  })
                )}
             </tbody>
           </table>
         </div>

         {/* Table Footer with Filter Reset */}
         <div className="border-t border-slate-100 dark:border-slate-700 p-3 bg-slate-50 dark:bg-slate-700/20 flex items-center justify-between">
            <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
                Total: {filteredTasks.length} {filteredTasks.length === 1 ? 'tarefa encontrada' : 'tarefas encontradas'}
            </span>
            {hasActiveFilters && (
                <button 
                    onClick={handleClearFilters}
                    className="flex items-center gap-1 text-xs font-bold text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-900/20 px-3 py-1.5 rounded transition-colors"
                >
                    <Eraser size={14} />
                    Limpar Tudo
                </button>
            )}
         </div>
      </div>

      <TaskFormModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        initialData={editingTask}
      />
    </div>
  );
};

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { Edit2, Save, X, Trash2, Plus, Calendar, CalendarDays, Upload, Briefcase, Filter, AlertTriangle, HardHat } from 'lucide-react';
import { ScheduleItem, MonthlyScheduleItem, ThirdPartyScheduleItem, Frequency } from '../../types';

export const Schedule = () => {
  const { 
    schedule, addScheduleItem, updateScheduleItem, deleteScheduleItem,
    monthlySchedule, addMonthlyScheduleItem, updateMonthlyScheduleItem, deleteMonthlyScheduleItem,
    thirdPartySchedule, addThirdPartyScheduleItem, updateThirdPartyScheduleItem, deleteThirdPartyScheduleItem,
    importDataFromCSV
  } = useData();

  const [activeTab, setActiveTab] = useState<'weekly' | 'monthly' | 'annual'>('weekly');
  const [activeFrequencyFilter, setActiveFrequencyFilter] = useState<Frequency | 'Todas'>('Todas');

  const [isModalOpen, setIsModalOpen] = useState(false);

  // Generic state for editing/adding
  const [editingWeekly, setEditingWeekly] = useState<Partial<ScheduleItem>>({});
  const [editingMonthly, setEditingMonthly] = useState<Partial<MonthlyScheduleItem>>({});
  const [editingThirdParty, setEditingThirdParty] = useState<Partial<ThirdPartyScheduleItem>>({});

  const handleAddNew = () => {
    if (activeTab === 'weekly') {
        setEditingWeekly({ shift: 'MANHÃ', monday: '', tuesday: '', wednesday: '', thursday: '', friday: '', saturday: '', workStartDate: '', workEndDate: '', workNoticeDate: '' });
        setEditingMonthly({});
        setEditingThirdParty({});
    } else if (activeTab === 'monthly') {
        setEditingMonthly({ shift: 'MANHÃ', week1: '', week2: '', week3: '', week4: '', workStartDate: '', workEndDate: '', workNoticeDate: '' });
        setEditingWeekly({});
        setEditingThirdParty({});
    } else {
        setEditingThirdParty({ company: '', service: '', frequency: 'Mensal', contact: '', workStartDate: '', workEndDate: '', workNoticeDate: '' });
        setEditingWeekly({});
        setEditingMonthly({});
    }
    setIsModalOpen(true);
  };

  const handleEditWeekly = (item: ScheduleItem) => {
    setEditingWeekly(item);
    setIsModalOpen(true);
  };

  const handleEditMonthly = (item: MonthlyScheduleItem) => {
    setEditingMonthly(item);
    setIsModalOpen(true);
  };

  const handleEditThirdParty = (item: ThirdPartyScheduleItem) => {
      setEditingThirdParty(item);
      setIsModalOpen(true);
  }

  const handleDeleteWeekly = (id: string) => {
      deleteScheduleItem(id);
  };

  const handleDeleteMonthly = (id: string) => {
      deleteMonthlyScheduleItem(id);
  };

  const handleDeleteThirdParty = (id: string) => {
      deleteThirdPartyScheduleItem(id);
  }

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = async (event) => {
          const content = event.target?.result as string;
          const result = await importDataFromCSV(content);
          alert(`${result.message}\n${result.count ? `Importados: ${result.count} registros.` : ''}`);
          e.target.value = ''; 
      };
      reader.readAsText(file);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (activeTab === 'weekly') {
        const payload = editingWeekly as ScheduleItem;
        if (!payload.shift) { alert("Informe o turno"); return; }
        if (payload.id) updateScheduleItem(payload.id, payload);
        else addScheduleItem(payload);
    } else if (activeTab === 'monthly') {
        const payload = editingMonthly as MonthlyScheduleItem;
        if (!payload.shift) { alert("Informe o turno/área"); return; }
        if (payload.id) updateMonthlyScheduleItem(payload.id, payload);
        else addMonthlyScheduleItem(payload);
    } else {
        const payload = editingThirdParty as ThirdPartyScheduleItem;
        if (!payload.company || !payload.service) { alert("Informe Empresa e Serviço"); return; }
        if (payload.id) updateThirdPartyScheduleItem(payload.id, payload);
        else addThirdPartyScheduleItem(payload);
    }
    setIsModalOpen(false);
  };

  const filteredThirdParty = activeFrequencyFilter === 'Todas' 
     ? thirdPartySchedule 
     : thirdPartySchedule.filter(tp => tp.frequency === activeFrequencyFilter);

  // Helper to format date just for display
  const formatDate = (dateStr?: string) => {
      if (!dateStr) return '-';
      const d = new Date(dateStr);
      if (isNaN(d.getTime())) return dateStr;
      return d.toLocaleDateString('pt-BR');
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Cronograma Operacional</h2>
           <p className="text-slate-500 dark:text-slate-400">Planejamento de rotinas de manutenção e obras</p>
        </div>
        <div className="flex items-center gap-2">
            <label className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors cursor-pointer">
              <Upload size={18} />
              <span className="hidden sm:inline">Importar</span>
              <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
            </label>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200 dark:shadow-none">
                <Plus size={18} /> Novo Item
            </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-4 border-b border-slate-200 dark:border-slate-700 overflow-x-auto">
         <button 
           onClick={() => setActiveTab('weekly')}
           className={`flex items-center gap-2 px-4 py-3 border-b-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'weekly' ? 'border-blue-600 text-blue-600 dark:text-blue-400' : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200'}`}
         >
             <CalendarDays size={18} />
             Semanal
         </button>
         <button 
           onClick={() => setActiveTab('monthly')}
           className={`flex items-center gap-2 px-4 py-3 border-b-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'monthly' ? 'border-blue-600 text-blue-600 dark:text-blue-400' : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200'}`}
         >
             <Calendar size={18} />
             Mensal
         </button>
         <button 
           onClick={() => setActiveTab('annual')}
           className={`flex items-center gap-2 px-4 py-3 border-b-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'annual' ? 'border-blue-600 text-blue-600 dark:text-blue-400' : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200'}`}
         >
             <Briefcase size={18} />
             Terceiros / Anual
         </button>
      </div>

      {/* Frequency Filter for Annual Tab */}
      {activeTab === 'annual' && (
          <div className="flex gap-2 flex-wrap pb-2">
              {(['Todas', 'Semanal', 'Mensal', 'Trimestral', 'Semestral', 'Anual'] as const).map(freq => (
                  <button
                    key={freq}
                    onClick={() => setActiveFrequencyFilter(freq)}
                    className={`px-3 py-1 text-xs rounded-full border transition-colors ${
                        activeFrequencyFilter === freq 
                        ? 'bg-blue-600 text-white border-blue-600' 
                        : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-400 border-slate-200 dark:border-slate-700 hover:border-blue-400'
                    }`}
                  >
                      {freq}
                  </button>
              ))}
          </div>
      )}

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
        {activeTab === 'weekly' ? (
            <div className="overflow-x-auto">
            <table className="w-full text-center border-collapse">
                <thead>
                <tr className="bg-blue-50 dark:bg-slate-700/50 text-slate-700 dark:text-slate-200 text-xs uppercase font-bold tracking-wider">
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700 w-24">Turno</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700">Segunda</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700">Terça</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700">Quarta</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700">Quinta</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700">Sexta</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700">Sábado</th>
                    <th className="px-4 py-4 bg-orange-50 dark:bg-orange-900/10 text-orange-700 dark:text-orange-300 w-48">Dados da Obra</th>
                    <th className="px-4 py-4 w-16">Ações</th>
                </tr>
                </thead>
                <tbody className="text-sm divide-y divide-slate-100 dark:divide-slate-700">
                {schedule.map(item => (
                    <tr key={item.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                        <td className="px-4 py-4 font-bold text-blue-600 dark:text-blue-400 border-r border-slate-100 dark:border-slate-700">{item.shift}</td>
                        <td className="px-4 py-4 border-r border-slate-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-xs">{item.monday}</td>
                        <td className="px-4 py-4 border-r border-slate-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-xs">{item.tuesday}</td>
                        <td className="px-4 py-4 border-r border-slate-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-xs">{item.wednesday}</td>
                        <td className="px-4 py-4 border-r border-slate-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-xs">{item.thursday}</td>
                        <td className="px-4 py-4 border-r border-slate-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-xs">{item.friday}</td>
                        <td className="px-4 py-4 border-r border-slate-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-xs">{item.saturday}</td>
                        <td className="px-4 py-4 bg-orange-50/50 dark:bg-orange-900/5 text-xs">
                             {item.workStartDate || item.workEndDate ? (
                                 <div className="flex flex-col gap-1 text-left">
                                    <span className="text-orange-600 font-bold">Início: {formatDate(item.workStartDate)}</span>
                                    <span className="text-slate-500">Fim: {formatDate(item.workEndDate)}</span>
                                    {item.workNoticeDate && <span className="text-red-500 text-[10px]">Aviso: {formatDate(item.workNoticeDate)}</span>}
                                 </div>
                             ) : <span className="text-slate-400">-</span>}
                        </td>
                        <td className="px-4 py-4">
                            <div className="flex items-center justify-center gap-2">
                                <button onClick={() => handleEditWeekly(item)} className="p-1.5 text-slate-400 hover:text-blue-600"><Edit2 size={16} /></button>
                                <button onClick={() => handleDeleteWeekly(item.id)} className="p-1.5 text-slate-400 hover:text-red-600"><Trash2 size={16} /></button>
                            </div>
                        </td>
                    </tr>
                ))}
                </tbody>
            </table>
            </div>
        ) : activeTab === 'monthly' ? (
            <div className="overflow-x-auto">
            <table className="w-full text-center border-collapse">
                <thead>
                <tr className="bg-emerald-50 dark:bg-slate-700/50 text-slate-700 dark:text-slate-200 text-xs uppercase font-bold tracking-wider">
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700 w-24">Turno/Área</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700">Semana 1</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700">Semana 2</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700">Semana 3</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700">Semana 4</th>
                    <th className="px-4 py-4 bg-orange-50 dark:bg-orange-900/10 text-orange-700 dark:text-orange-300 w-48">Dados da Obra</th>
                    <th className="px-4 py-4 w-16">Ações</th>
                </tr>
                </thead>
                <tbody className="text-sm divide-y divide-slate-100 dark:divide-slate-700">
                {monthlySchedule.map(item => (
                    <tr key={item.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                        <td className="px-4 py-4 font-bold text-emerald-600 dark:text-emerald-400 border-r border-slate-100 dark:border-slate-700">{item.shift}</td>
                        <td className="px-4 py-4 border-r border-slate-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-xs">{item.week1}</td>
                        <td className="px-4 py-4 border-r border-slate-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-xs">{item.week2}</td>
                        <td className="px-4 py-4 border-r border-slate-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-xs">{item.week3}</td>
                        <td className="px-4 py-4 border-r border-slate-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-xs">{item.week4}</td>
                        <td className="px-4 py-4 bg-orange-50/50 dark:bg-orange-900/5 text-xs">
                             {item.workStartDate || item.workEndDate ? (
                                 <div className="flex flex-col gap-1 text-left">
                                    <span className="text-orange-600 font-bold">Início: {formatDate(item.workStartDate)}</span>
                                    <span className="text-slate-500">Fim: {formatDate(item.workEndDate)}</span>
                                    {item.workNoticeDate && <span className="text-red-500 text-[10px]">Aviso: {formatDate(item.workNoticeDate)}</span>}
                                 </div>
                             ) : <span className="text-slate-400">-</span>}
                        </td>
                        <td className="px-4 py-4">
                            <div className="flex items-center justify-center gap-2">
                                <button onClick={() => handleEditMonthly(item)} className="p-1.5 text-slate-400 hover:text-blue-600"><Edit2 size={16} /></button>
                                <button onClick={() => handleDeleteMonthly(item.id)} className="p-1.5 text-slate-400 hover:text-red-600"><Trash2 size={16} /></button>
                            </div>
                        </td>
                    </tr>
                ))}
                </tbody>
            </table>
            </div>
        ) : (
            // ANNUAL / THIRD PARTY TABLE
            <div className="overflow-x-auto">
            <table className="w-full text-center border-collapse">
                <thead>
                <tr className="bg-purple-50 dark:bg-slate-700/50 text-slate-700 dark:text-slate-200 text-xs uppercase font-bold tracking-wider">
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700 text-left">Empresa</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700 text-left">Serviço</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700">Frequência</th>
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700">Contato</th>
                    <th className="px-4 py-4 bg-orange-50 dark:bg-orange-900/10 text-orange-700 dark:text-orange-300 w-48">Dados da Obra</th>
                    <th className="px-4 py-4 w-16">Ações</th>
                </tr>
                </thead>
                <tbody className="text-sm divide-y divide-slate-100 dark:divide-slate-700">
                {filteredThirdParty.length === 0 ? (
                    <tr>
                        <td colSpan={6} className="p-8 text-center text-slate-500">Nenhum registro encontrado.</td>
                    </tr>
                ) : (
                    filteredThirdParty.map(item => (
                    <tr key={item.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                        <td className="px-4 py-4 text-left font-bold text-slate-800 dark:text-white border-r border-slate-100 dark:border-slate-700">{item.company}</td>
                        <td className="px-4 py-4 text-left border-r border-slate-100 dark:border-slate-700 text-slate-600 dark:text-slate-300">{item.service}</td>
                        <td className="px-4 py-4 border-r border-slate-100 dark:border-slate-700 text-center">
                            <span className="px-2 py-1 rounded bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-300 text-xs font-bold">
                                {item.frequency}
                            </span>
                        </td>
                        <td className="px-4 py-4 border-r border-slate-100 dark:border-slate-700 text-slate-500 dark:text-slate-400 text-xs">{item.contact}</td>
                        <td className="px-4 py-4 bg-orange-50/50 dark:bg-orange-900/5 text-xs">
                             {item.workStartDate || item.workEndDate ? (
                                 <div className="flex flex-col gap-1 text-left">
                                    <span className="text-orange-600 font-bold">Início: {formatDate(item.workStartDate)}</span>
                                    <span className="text-slate-500">Fim: {formatDate(item.workEndDate)}</span>
                                    {item.workNoticeDate && <span className="text-red-500 text-[10px]">Aviso: {formatDate(item.workNoticeDate)}</span>}
                                 </div>
                             ) : <span className="text-slate-400">-</span>}
                        </td>
                        <td className="px-4 py-4">
                            <div className="flex items-center justify-center gap-2">
                                <button onClick={() => handleEditThirdParty(item)} className="p-1.5 text-slate-400 hover:text-blue-600"><Edit2 size={16} /></button>
                                <button onClick={() => handleDeleteThirdParty(item.id)} className="p-1.5 text-slate-400 hover:text-red-600"><Trash2 size={16} /></button>
                            </div>
                        </td>
                    </tr>
                )))}
                </tbody>
            </table>
            </div>
        )}
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4">
            <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-2xl border border-slate-200 dark:border-slate-700 shadow-xl max-h-[90vh] overflow-y-auto">
                <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center">
                    <h3 className="font-bold text-lg text-slate-800 dark:text-white">
                        {activeTab === 'weekly' ? 'Editar Semanal' : activeTab === 'monthly' ? 'Editar Mensal' : 'Editar Terceiros/Anual'}
                    </h3>
                    <button type="button" onClick={() => setIsModalOpen(false)}><X className="text-slate-400" /></button>
                </div>
                <form onSubmit={handleSave} className="p-6 space-y-6">

                    {/* FIELDS FOR WEEKLY */}
                    {activeTab === 'weekly' && (
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm mb-1 text-slate-600 dark:text-slate-400">Turno</label>
                                <select 
                                    value={editingWeekly.shift || ''} 
                                    onChange={e => setEditingWeekly({...editingWeekly, shift: e.target.value})}
                                    className="w-full p-2 rounded border dark:bg-slate-900 dark:border-slate-700 dark:text-white"
                                >
                                    <option value="MANHÃ">MANHÃ</option>
                                    <option value="TARDE">TARDE</option>
                                    <option value="NOITE">NOITE</option>
                                    <option value="ADM">ADM</option>
                                </select>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                {['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'].map(day => (
                                    <div key={day}>
                                        <label className="block text-sm mb-1 text-slate-600 dark:text-slate-400 capitalize">{day}</label>
                                        <input 
                                            type="text"
                                            value={(editingWeekly as any)[day] || ''}
                                            onChange={e => setEditingWeekly({...editingWeekly, [day]: e.target.value})}
                                            className="w-full p-2 rounded border dark:bg-slate-900 dark:border-slate-700 dark:text-white"
                                        />
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* FIELDS FOR MONTHLY */}
                    {activeTab === 'monthly' && (
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm mb-1 text-slate-600 dark:text-slate-400">Turno / Área</label>
                                <input 
                                    type="text"
                                    value={editingMonthly.shift || ''} 
                                    onChange={e => setEditingMonthly({...editingMonthly, shift: e.target.value})}
                                    className="w-full p-2 rounded border dark:bg-slate-900 dark:border-slate-700 dark:text-white"
                                    placeholder="Ex: MANHÃ ou JARDINAGEM"
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                {['week1', 'week2', 'week3', 'week4'].map(week => (
                                    <div key={week}>
                                        <label className="block text-sm mb-1 text-slate-600 dark:text-slate-400 capitalize">{week.replace('week', 'Semana ')}</label>
                                        <textarea 
                                            value={(editingMonthly as any)[week] || ''}
                                            onChange={e => setEditingMonthly({...editingMonthly, [week]: e.target.value})}
                                            className="w-full p-2 rounded border dark:bg-slate-900 dark:border-slate-700 dark:text-white h-20"
                                        />
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* FIELDS FOR ANNUAL / THIRD PARTY */}
                    {activeTab === 'annual' && (
                        <div className="space-y-4">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm mb-1 text-slate-600 dark:text-slate-400">Empresa</label>
                                    <input 
                                        type="text"
                                        value={editingThirdParty.company || ''} 
                                        onChange={e => setEditingThirdParty({...editingThirdParty, company: e.target.value})}
                                        className="w-full p-2 rounded border dark:bg-slate-900 dark:border-slate-700 dark:text-white"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm mb-1 text-slate-600 dark:text-slate-400">Serviço</label>
                                    <input 
                                        type="text"
                                        value={editingThirdParty.service || ''} 
                                        onChange={e => setEditingThirdParty({...editingThirdParty, service: e.target.value})}
                                        className="w-full p-2 rounded border dark:bg-slate-900 dark:border-slate-700 dark:text-white"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm mb-1 text-slate-600 dark:text-slate-400">Frequência</label>
                                    <select 
                                        value={editingThirdParty.frequency || 'Mensal'} 
                                        onChange={e => setEditingThirdParty({...editingThirdParty, frequency: e.target.value as Frequency})}
                                        className="w-full p-2 rounded border dark:bg-slate-900 dark:border-slate-700 dark:text-white"
                                    >
                                        <option value="Semanal">Semanal</option>
                                        <option value="Mensal">Mensal</option>
                                        <option value="Trimestral">Trimestral</option>
                                        <option value="Semestral">Semestral</option>
                                        <option value="Anual">Anual</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-sm mb-1 text-slate-600 dark:text-slate-400">Contato</label>
                                    <input 
                                        type="text"
                                        value={editingThirdParty.contact || ''} 
                                        onChange={e => setEditingThirdParty({...editingThirdParty, contact: e.target.value})}
                                        className="w-full p-2 rounded border dark:bg-slate-900 dark:border-slate-700 dark:text-white"
                                    />
                                </div>
                            </div>
                        </div>
                    )}

                    {/* COMMON WORK FIELDS FOR ALL TABS */}
                    <div className="pt-4 border-t border-slate-100 dark:border-slate-700">
                        <h4 className="flex items-center gap-2 text-sm font-bold text-orange-600 dark:text-orange-400 uppercase mb-4">
                            <HardHat size={16} /> Dados da Obra (Opcional)
                        </h4>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-orange-50 dark:bg-orange-900/10 p-4 rounded-xl border border-orange-100 dark:border-orange-900/30">
                            <div>
                                <label className="block text-xs font-bold text-orange-700 dark:text-orange-300 mb-1">Início da Obra</label>
                                <input 
                                    type="date"
                                    value={
                                        activeTab === 'weekly' ? editingWeekly.workStartDate || '' :
                                        activeTab === 'monthly' ? editingMonthly.workStartDate || '' :
                                        editingThirdParty.workStartDate || ''
                                    }
                                    onChange={e => {
                                        const val = e.target.value;
                                        if (activeTab === 'weekly') setEditingWeekly({...editingWeekly, workStartDate: val});
                                        else if (activeTab === 'monthly') setEditingMonthly({...editingMonthly, workStartDate: val});
                                        else setEditingThirdParty({...editingThirdParty, workStartDate: val});
                                    }}
                                    className="w-full p-2 rounded border border-orange-200 dark:border-orange-800 dark:bg-slate-900 dark:text-white text-sm"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-orange-700 dark:text-orange-300 mb-1">Término da Obra</label>
                                <input 
                                    type="date"
                                    value={
                                        activeTab === 'weekly' ? editingWeekly.workEndDate || '' :
                                        activeTab === 'monthly' ? editingMonthly.workEndDate || '' :
                                        editingThirdParty.workEndDate || ''
                                    }
                                    onChange={e => {
                                        const val = e.target.value;
                                        if (activeTab === 'weekly') setEditingWeekly({...editingWeekly, workEndDate: val});
                                        else if (activeTab === 'monthly') setEditingMonthly({...editingMonthly, workEndDate: val});
                                        else setEditingThirdParty({...editingThirdParty, workEndDate: val});
                                    }}
                                    className="w-full p-2 rounded border border-orange-200 dark:border-orange-800 dark:bg-slate-900 dark:text-white text-sm"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-red-600 dark:text-red-400 mb-1 flex items-center gap-1"><AlertTriangle size={12}/> Data de Aviso</label>
                                <input 
                                    type="date"
                                    value={
                                        activeTab === 'weekly' ? editingWeekly.workNoticeDate || '' :
                                        activeTab === 'monthly' ? editingMonthly.workNoticeDate || '' :
                                        editingThirdParty.workNoticeDate || ''
                                    }
                                    onChange={e => {
                                        const val = e.target.value;
                                        if (activeTab === 'weekly') setEditingWeekly({...editingWeekly, workNoticeDate: val});
                                        else if (activeTab === 'monthly') setEditingMonthly({...editingMonthly, workNoticeDate: val});
                                        else setEditingThirdParty({...editingThirdParty, workNoticeDate: val});
                                    }}
                                    className="w-full p-2 rounded border border-red-200 dark:border-red-800 dark:bg-slate-900 dark:text-white text-sm"
                                />
                            </div>
                        </div>
                    </div>

                    <div className="flex justify-end pt-4 gap-2 border-t border-slate-100 dark:border-slate-700">
                        <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">Cancelar</button>
                        <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2"><Save size={16}/> Salvar Item</button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { useAuth } from '../../context/AuthContext';
import { Plus, Search, Filter, Download, Edit2, Trash2, Wrench, Upload, Eraser, Calendar } from 'lucide-react';
import { TaskFormModal } from '../ui/TaskFormModal';
import { Task } from '../../types';

export const TaskList = () => {
  const { tasks, settings, deleteTask, exportTasksToCSV, importDataFromCSV } = useData();
  const { user } = useAuth();
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Filter States
  const [searchTerm, setSearchTerm] = useState('');
  const [filterSituation, setFilterSituation] = useState('Todos');
  const [dateFilter, setDateFilter] = useState<'all' | 'week' | 'month'>('all');

  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  // Helper para buscar nomes (com fallback caso o ID seja o próprio nome importado)
  const findName = (list: any[], id: string, defaultLabel: string) => {
      const found = list.find(i => i.id === id);
      return found ? found.name : (id || defaultLabel);
  };

  const getResponsibleName = (id: string) => findName(settings.responsibles, id, 'N/A');
  const getSectorName = (id: string) => findName(settings.sectors, id, 'N/A');
  const getServiceName = (id: string) => findName(settings.services, id, 'Serviço');
  const getTowerName = (id: string) => findName(settings.towers, id, 'Torre');

  const getMaterialNames = (ids: string[]) => {
      if (!ids || ids.length === 0) return null;
      return ids.map(id => settings.materials.find(m => m.id === id)?.name || id).filter(Boolean).join(', ');
  };

  const handleEdit = (task: Task) => {
    setEditingTask(task);
    setIsModalOpen(true);
  };

  const handleConfirmDelete = (id: string) => {
      if (window.confirm('ATENÇÃO: Tem certeza que deseja excluir esta tarefa permanentemente?')) {
          deleteTask(id);
      }
  };

  const handleAddNew = () => {
    setEditingTask(undefined);
    setIsModalOpen(true);
  };

  const handleClearFilters = () => {
      setSearchTerm('');
      setFilterSituation('Todos');
      setDateFilter('all');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = async (event) => {
          const content = event.target?.result as string;
          const result = await importDataFromCSV(content);
          alert(`${result.message}\n${result.count ? `Importados: ${result.count} registros.` : ''}`);
          e.target.value = ''; 
      };
      reader.readAsText(file);
  };

  // Helper de Data Segura
  const parseTaskDate = (dateString: string) => {
      if (!dateString) return new Date(0); // Data muito antiga
      // Tenta ISO
      let d = new Date(dateString);
      if (!isNaN(d.getTime())) return d;

      // Tenta BR (DD/MM/YYYY)
      if (dateString.includes('/')) {
          const [day, month, year] = dateString.split('/');
          d = new Date(Number(year), Number(month) - 1, Number(day));
          if (!isNaN(d.getTime())) return d;
      }
      return new Date(0);
  };

  const filteredTasks = tasks.filter(task => {
    const term = searchTerm.toLowerCase().trim();

    // 1. Search Filter (Robust)
    const serviceName = getServiceName(task.serviceId).toLowerCase();
    const towerName = getTowerName(task.towerId).toLowerCase();
    const title = (task.title || '').toLowerCase();
    const location = (task.location || '').toLowerCase();
    const responsible = getResponsibleName(task.responsibleId).toLowerCase();

    const matchesSearch = term === '' || 
                          title.includes(term) || 
                          location.includes(term) ||
                          serviceName.includes(term) ||
                          towerName.includes(term) ||
                          responsible.includes(term);

    // 2. Situation Filter (Normalization: "Em Andamento" == "EM ANDAMENTO")
    const taskSit = (task.situation || '').toLowerCase().trim();
    const filterSit = filterSituation.toLowerCase().trim();
    const matchesSituation = filterSituation === 'Todos' || taskSit === filterSit;

    // 3. Date Filter (Based on Call Date)
    let matchesDate = true;
    if (dateFilter !== 'all') {
        const taskDate = parseTaskDate(task.callDate);
        taskDate.setHours(0,0,0,0);

        const now = new Date();
        now.setHours(0,0,0,0);

        if (dateFilter === 'month') {
            matchesDate = taskDate.getMonth() === now.getMonth() && taskDate.getFullYear() === now.getFullYear();
        } else if (dateFilter === 'week') {
            const startOfWeek = new Date(now);
            startOfWeek.setDate(now.getDate() - now.getDay()); // Sunday

            const endOfWeek = new Date(startOfWeek);
            endOfWeek.setDate(startOfWeek.getDate() + 6); // Saturday

            matchesDate = taskDate >= startOfWeek && taskDate <= endOfWeek;
        }
    }

    return matchesSearch && matchesSituation && matchesDate;
  });

  // Robust Status Coloring (Case Insensitive)
  const getStatusColor = (status: string) => {
    const s = status?.toLowerCase() || '';
    if (s.includes('conclu')) return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300 border-blue-200 dark:border-blue-800';
    if (s.includes('andamento') || s.includes('execu')) return 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/30 dark:text-cyan-300 border-cyan-200 dark:border-cyan-800';
    if (s.includes('cancel')) return 'bg-slate-100 text-slate-600 dark:bg-slate-700 dark:text-slate-300 border-slate-200 dark:border-slate-600';
    return 'bg-indigo-50 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-300 border-indigo-200 dark:border-indigo-800'; // Aberto/Outros
  };

  // Robust Criticality Coloring
  const getCriticalityColor = (crit: string) => {
    const c = crit?.toLowerCase() || '';
    if (c.includes('alt') || c.includes('high') || c.includes('urge') || c.includes('crit')) return 'text-red-600 bg-red-50 border-red-200 dark:bg-red-900/20 dark:text-red-400 dark:border-red-900/50 shadow-[0_0_10px_rgba(239,68,68,0.1)]';
    if (c.includes('méd') || c.includes('med')) return 'text-amber-600 bg-amber-50 border-amber-200 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-900/50';
    return 'text-emerald-600 bg-emerald-50 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-900/50'; // Baixa/Low
  };

  // Maintenance Type Color
  const getTypeColor = (type?: string) => {
      switch(type) {
          case 'Corretiva': return 'bg-red-50 text-red-600 border-red-100 dark:bg-red-900/20 dark:border-red-900/30 dark:text-red-300';
          case 'Preventiva': return 'bg-blue-50 text-blue-600 border-blue-100 dark:bg-blue-900/20 dark:border-blue-900/30 dark:text-blue-300';
          case 'Programada': return 'bg-purple-50 text-purple-600 border-purple-100 dark:bg-purple-900/20 dark:border-purple-900/30 dark:text-purple-300';
          default: return 'bg-slate-50 text-slate-500';
      }
  };

  // Short Date Formatter (DD/MM)
  const formatShortDate = (dateString?: string) => {
      if (!dateString || dateString.trim() === '') return '-';
      const d = parseTaskDate(dateString);
      if (d.getTime() === 0) return dateString.substring(0, 5); // Fallback to string chop if parse fails completely
      return d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });
  };

  const hasActiveFilters = searchTerm !== '' || filterSituation !== 'Todos' || dateFilter !== 'all';

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Tarefas de Manutenção</h2>
          <p className="text-slate-500 dark:text-slate-400">Gerencie todas as ordens de serviço</p>
        </div>
        <div className="flex gap-2">
           <label className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors cursor-pointer">
              <Upload size={18} />
              <span className="hidden sm:inline">Importar</span>
              <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
           </label>
           <button onClick={exportTasksToCSV} className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
              <Download size={18} />
              <span className="hidden sm:inline">Exportar</span>
           </button>
           <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm shadow-blue-200 dark:shadow-none transition-all transform active:scale-95">
              <Plus size={18} />
              <span>Nova Tarefa</span>
           </button>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col xl:flex-row gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
         <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Buscar por serviço, torre, local, responsável..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm text-slate-800 dark:text-slate-200 placeholder-slate-400"
            />
         </div>
         <div className="flex flex-wrap items-center gap-2">

            {/* Situation Filter */}
            <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-900 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700">
                <Filter size={16} className="text-slate-400" />
                <select 
                value={filterSituation}
                onChange={(e) => setFilterSituation(e.target.value)}
                className="bg-transparent text-sm text-slate-600 dark:text-slate-300 focus:outline-none"
                >
                <option value="Todos">Todas as Situações</option>
                {settings.situations.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                </select>
            </div>

            {/* Date Filter */}
            <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-900 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700">
                <Calendar size={16} className="text-slate-400" />
                <select 
                value={dateFilter}
                onChange={(e) => setDateFilter(e.target.value as any)}
                className="bg-transparent text-sm text-slate-600 dark:text-slate-300 focus:outline-none"
                >
                <option value="all">Todo o Período</option>
                <option value="week">Esta Semana</option>
                <option value="month">Este Mês</option>
                </select>
            </div>

            {/* Clear Button (Top) */}
            {hasActiveFilters && (
                <button 
                    onClick={handleClearFilters}
                    className="flex items-center gap-2 px-3 py-2 text-sm text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors border border-transparent hover:border-red-100"
                >
                    <Eraser size={16} />
                    Limpar
                </button>
            )}
         </div>
      </div>

      {/* Table Container */}
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden flex flex-col">
         <div className="overflow-x-auto">
           <table className="w-full text-left border-collapse min-w-[1000px]">
             <thead>
               <tr className="bg-slate-50 dark:bg-slate-700/50 border-b border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 text-xs uppercase font-semibold">
                 <th className="px-3 py-3 w-[25%]">Serviço / Torre / Tipo</th>
                 <th className="px-3 py-3 w-[15%]">Datas (Ab/In/Fi)</th>
                 <th className="px-3 py-3 w-[15%]">Local / Setor</th>
                 <th className="px-3 py-3">Responsável</th>
                 <th className="px-3 py-3 text-center">Mat.</th>
                 <th className="px-3 py-3 text-center">Situação</th>
                 <th className="px-3 py-3 text-center">Crit.</th>
                 <th className="px-3 py-3 text-right">Ações</th>
               </tr>
             </thead>
             <tbody className="text-sm divide-y divide-slate-100 dark:divide-slate-700">
                {filteredTasks.length === 0 ? (
                  <tr>
                    <td colSpan={8} className="px-4 py-8 text-center text-slate-400 dark:text-slate-500">
                       Nenhuma tarefa encontrada.
                    </td>
                  </tr>
                ) : (
                  filteredTasks.map((task) => {
                      const materialNames = getMaterialNames(task.materials);
                      return (
                        <tr key={task.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                            {/* Service / Tower / Type */}
                            <td className="px-3 py-3 align-top">
                                <div className="font-bold text-slate-800 dark:text-slate-200 flex items-start gap-2 text-sm">
                                    <Wrench size={14} className="text-blue-500 shrink-0 mt-0.5" />
                                    <span className="leading-tight">{getServiceName(task.serviceId)}</span>
                                </div>
                                <div className="flex items-center gap-2 mt-1 pl-6">
                                    <span className="text-xs font-semibold text-blue-600 dark:text-blue-400">
                                        {getTowerName(task.towerId)}
                                    </span>
                                    <span className={`text-[9px] px-1.5 py-0.5 rounded border uppercase tracking-wider ${getTypeColor(task.type)}`}>
                                        {task.type || 'Corretiva'}
                                    </span>
                                </div>
                            </td>

                            {/* Consolidated Dates */}
                            <td className="px-3 py-3 align-top">
                                <div className="flex flex-col gap-0.5 text-xs font-mono">
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-slate-400">Ab:</span> 
                                        {formatShortDate(task.callDate)}
                                    </div>
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-emerald-600 dark:text-emerald-500">In:</span> 
                                        {formatShortDate(task.startDate)}
                                    </div>
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-indigo-500">Fi:</span> 
                                        {formatShortDate(task.endDate)}
                                    </div>
                                </div>
                            </td>

                            {/* Location / Sector */}
                            <td className="px-3 py-3 align-top">
                                <div className="text-slate-700 dark:text-slate-300 font-medium text-sm leading-tight truncate max-w-[150px]" title={task.location}>
                                    {task.location}
                                </div>
                                <div className="text-xs text-slate-400 dark:text-slate-500 mt-0.5">
                                    {getSectorName(task.sectorId)}
                                </div>
                            </td>

                            {/* Responsible */}
                            <td className="px-3 py-3 align-top text-slate-600 dark:text-slate-400 text-xs">
                                <div className="truncate max-w-[120px]" title={getResponsibleName(task.responsibleId)}>
                                    {getResponsibleName(task.responsibleId)}
                                </div>
                            </td>

                            {/* Materials */}
                            <td className="px-3 py-3 text-center align-top">
                                {materialNames ? (
                                    <div className="group relative cursor-help flex justify-center">
                                        <span className="w-5 h-5 flex items-center justify-center rounded bg-emerald-100 text-emerald-700 text-[10px] font-bold">
                                            Sim
                                        </span>
                                        <div className="absolute hidden group-hover:block right-0 top-full mt-1 bg-slate-800 text-white text-[10px] p-2 rounded shadow-lg z-10 w-32 text-left">
                                            {materialNames}
                                        </div>
                                    </div>
                                ) : (
                                    <span className="text-slate-300 dark:text-slate-600 text-lg leading-none">-</span>
                                )}
                            </td>

                            {/* Situation */}
                            <td className="px-3 py-3 text-center align-top">
                                <span className={`inline-block px-2.5 py-1 rounded-full text-[10px] font-bold border uppercase tracking-wider ${getStatusColor(task.situation)}`}>
                                    {task.situation}
                                </span>
                            </td>

                            {/* Criticality */}
                            <td className="px-3 py-3 text-center align-top">
                                <span className={`inline-block px-2.5 py-1 rounded-md text-[10px] font-bold border uppercase tracking-wider ${getCriticalityColor(task.criticality)}`}>
                                    {task.criticality}
                                </span>
                            </td>

                            {/* Actions */}
                            <td className="px-3 py-3 text-right align-top">
                                <div className="flex items-center justify-end gap-1">
                                    <button onClick={() => handleEdit(task)} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded transition-colors" title="Editar">
                                    <Edit2 size={16} />
                                    </button>
                                    {user?.role === 'admin' && (
                                    <button onClick={() => handleConfirmDelete(task.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded transition-colors" title="Excluir">
                                        <Trash2 size={16} />
                                    </button>
                                    )}
                                </div>
                            </td>
                        </tr>
                      );
                  })
                )}
             </tbody>
           </table>
         </div>

         {/* Table Footer with Filter Reset */}
         <div className="border-t border-slate-100 dark:border-slate-700 p-3 bg-slate-50 dark:bg-slate-700/20 flex items-center justify-between">
            <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
                Total: {filteredTasks.length} {filteredTasks.length === 1 ? 'tarefa encontrada' : 'tarefas encontradas'}
            </span>
            {hasActiveFilters && (
                <button 
                    onClick={handleClearFilters}
                    className="flex items-center gap-1 text-xs font-bold text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-900/20 px-3 py-1.5 rounded transition-colors"
                >
                    <Eraser size={14} />
                    Limpar Tudo
                </button>
            )}
         </div>
      </div>

      <TaskFormModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        initialData={editingTask}
      />
    </div>
  );
};

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { Search, Plus, Edit2, Trash2, X, Save, Upload } from 'lucide-react';
import { Visit } from '../../types';

export const Visits = () => {
  const { visits, addVisit, updateVisit, deleteVisit, settings, importDataFromCSV } = useData();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<Partial<Visit>>({});
  const [searchTerm, setSearchTerm] = useState('');

  const handleAddNew = () => {
      setEditingItem({});
      setIsModalOpen(true);
  };

  const handleEdit = (item: Visit) => {
      setEditingItem(item);
      setIsModalOpen(true);
  };

  const handleDelete = (id: string) => {
      if(window.confirm("ATENÇÃO: Deseja realmente excluir esta visita? A ação não poderá ser desfeita.")) {
          deleteVisit(id);
      }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = async (event) => {
          const content = event.target?.result as string;
          const result = await importDataFromCSV(content);
          alert(`${result.message}\n${result.count ? `Importados: ${result.count} registros.` : ''}`);
          e.target.value = ''; 
      };
      reader.readAsText(file);
  };

  const handleSave = (e: React.FormEvent) => {
      e.preventDefault();
      const payload = {
          tower: editingItem.tower || '',
          unit: editingItem.unit || '',
          situation: editingItem.situation || '',
          time: editingItem.time || '',
          collaborator: editingItem.collaborator || '',
          status: editingItem.status || 'Pendente',
          returnDate: editingItem.returnDate || '-'
      } as Visit;

      if (editingItem.id) {
          updateVisit(editingItem.id, payload);
      } else {
          addVisit(payload);
      }
      setIsModalOpen(false);
  };

  const getStatusStyle = (status: string) => {
      const s = status?.toLowerCase() || '';
      if (s.includes('conclu')) return 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300 border border-green-200 dark:border-green-800';
      if (s.includes('pendente')) return 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300 border border-amber-200 dark:border-amber-800';
      return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300 border border-blue-200 dark:border-blue-800';
  };

  const filteredVisits = visits.filter(visit => {
      const term = searchTerm.toLowerCase();
      return (
          visit.unit?.toLowerCase().includes(term) ||
          visit.tower?.toLowerCase().includes(term) ||
          visit.collaborator?.toLowerCase().includes(term) ||
          visit.situation?.toLowerCase().includes(term)
      );
  });

  return (
