                                    <span className="text-slate-500">Fim: {formatDate(item.workEndDate)}</span>
                                    {item.workNoticeDate && <span className="text-red-500 text-[10px]">Aviso: {formatDate(item.workNoticeDate)}</span>}
                                 </div>
