    importDataFromCSV
  } = useData();

  const [activeTab, setActiveTab] = useState<'weekly' | 'monthly'>('weekly');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<any>({});

  const handleAddNew = () => {
    setEditingItem(activeTab === 'weekly' ? {
        shift: 'MANHÃ', monday: '', tuesday: '', wednesday: '', thursday: '', friday: '', saturday: ''
    } : {
        shift: 'ÁREA', week1: '', week2: '', week3: '', week4: ''
    });
    setIsModalOpen(true);
  };

  const handleEdit = (item: any) => {
      setEditingItem(item);
      setIsModalOpen(true);
  }

  const handleDelete = (id: string) => {
      if(window.confirm('Excluir item do cronograma?')) {
          if (activeTab === 'weekly') deleteScheduleItem(id);
          else deleteMonthlyScheduleItem(id);
      }
  }

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = async (event) => {
          const content = event.target?.result as string;
          const result = await importDataFromCSV(content);
          alert(`${result.message}\n${result.count ? `Importados: ${result.count} registros.` : ''}`);
          e.target.value = ''; 
      };
      reader.readAsText(file);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (activeTab === 'weekly') {
        const payload = editingItem as ScheduleItem;
        if (payload.id) updateScheduleItem(payload.id, payload);
        else addScheduleItem(payload);
    } else {
        const payload = editingItem as MonthlyScheduleItem;
        if (payload.id) updateMonthlyScheduleItem(payload.id, payload);
        else addMonthlyScheduleItem(payload);
    }
    setIsModalOpen(false);
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-2xl font-bold text-slate-800 dark:text-white flex items-center gap-2">
               <CalendarDays className="text-blue-500" />
               Cronograma Interno
           </h2>
           <p className="text-slate-500 dark:text-slate-400">Rotinas de funcionários e colaboradores internos</p>
        </div>
        <div className="flex gap-2">
            <label className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors cursor-pointer">
              <Upload size={18} />
              <span className="hidden sm:inline">Importar</span>
              <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
            </label>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200 dark:shadow-none">
                <Plus size={18} /> Novo Item
            </button>
        </div>
      </div>

      <div className="flex gap-4 border-b border-slate-200 dark:border-slate-700">
          <button 
             onClick={() => setActiveTab('weekly')}
             className={`pb-3 px-2 text-sm font-medium transition-colors relative ${activeTab === 'weekly' ? 'text-blue-600 dark:text-blue-400' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
          >
              Semanal (Turnos)
              {activeTab === 'weekly' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-blue-600 dark:bg-blue-400 rounded-t-full"></div>}
          </button>
          <button 
             onClick={() => setActiveTab('monthly')}
             className={`pb-3 px-2 text-sm font-medium transition-colors relative ${activeTab === 'monthly' ? 'text-blue-600 dark:text-blue-400' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
          >
              Mensal (Geral)
              {activeTab === 'monthly' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-blue-600 dark:bg-blue-400 rounded-t-full"></div>}
          </button>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
        <div className="overflow-x-auto">
        {activeTab === 'weekly' ? (
            <table className="w-full text-center border-collapse">
                <thead>
                <tr className="bg-slate-50 dark:bg-slate-700/50 text-slate-700 dark:text-slate-200 text-xs uppercase font-bold tracking-wider">
                    <th className="px-4 py-4 border-r border-slate-200 dark:border-slate-700 w-32">Turno</th>
                    <th className="px-2 py-4 border-r border-slate-200 dark:border-slate-700">Segunda</th>
                    <th className="px-2 py-4 border-r border-slate-200 dark:border-slate-700">Terça</th>
                    <th className="px-2 py-4 border-r border-slate-200 dark:border-slate-700">Quarta</th>
                    <th className="px-2 py-4 border-r border-slate-200 dark:border-slate-700">Quinta</th>
                    <th className="px-2 py-4 border-r border-slate-200 dark:border-slate-700">Sexta</th>
