            <div className="flex items-center gap-4">
                <button 
                   onClick={handleHardReload}
                   className="flex items-center gap-2 text-slate-400 hover:text-white transition-colors"
                   title="Forçar recarregamento da aplicação"
                >
                    <RefreshCw size={12} />
                    RELOAD APP
