     // Init last 7 days with 0
     for(let i=6; i>=0; i--) {
         const d = new Date(today);
         d.setDate(today.getDate() - i);
         const key = d.toLocaleDateString('pt-BR', {weekday: 'short'});
         daysMap.set(key, 0);
     }

