        {/* Changed Grid to 3 cols usually, can go 4 if large screen */}
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-5 gap-6">

            {/* OBRAS CARD (NEW) */}
