import React, { ReactNode } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import { DataProvider } from './context/DataContext';
import { ThemeProvider } from './context/ThemeContext';
import { Layout } from './components/ui/Layout';
import { Login } from './components/pages/Login';
import { Dashboard } from './components/pages/Dashboard';
import { TaskList } from './components/pages/TaskList';
import { Settings } from './components/pages/Settings';
import { Visits } from './components/pages/Visits';
import { Schedule } from './components/pages/Schedule';
import { Painting } from './components/pages/Painting';
import { Purchases } from './components/pages/Purchases';

const ProtectedRoute = ({ children }: { children?: ReactNode }) => {
  const { user } = useAuth();
  if (!user) {
    return <Login />;
  }
  return <>{children}</>;
};

const AdminRoute = ({ children }: { children?: ReactNode }) => {
  const { user } = useAuth();
  if (user?.role !== 'admin') {
    return <Navigate to="/" replace />;
  }
  return <>{children}</>;
};

const AppContent = () => {
  return (
    <Routes>
      <Route path="/" element={
        <ProtectedRoute>
          <Layout />
        </ProtectedRoute>
      }>
        <Route index element={<Dashboard />} />
        <Route path="tasks" element={<TaskList />} />
        <Route path="visits" element={<Visits />} />
        <Route path="schedule" element={<Schedule />} />
        <Route path="painting" element={<Painting />} />
        <Route path="purchases" element={<Purchases />} />
        <Route path="settings" element={
          <AdminRoute>
            <Settings />
          </AdminRoute>
        } />
      </Route>
    </Routes>
  );
}

export default function App() {
  return (
    <ThemeProvider>
      <AuthProvider>
        <DataProvider>
          <HashRouter>
             <AppContent />
          </HashRouter>
        </DataProvider>
      </AuthProvider>
    </ThemeProvider>
  );
}

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { Edit2, Save, X, Trash2, Plus, Upload, Download, Briefcase, Filter, AlertTriangle, CalendarRange, HardHat } from 'lucide-react';
import { ThirdPartyScheduleItem, Frequency } from '../../types';

export const Schedule = () => {
  const { 
    thirdPartySchedule, 
    addThirdPartyScheduleItem, 
    updateThirdPartyScheduleItem, 
    deleteThirdPartyScheduleItem,
    importDataFromCSV,
    exportThirdPartyToCSV
  } = useData();

  const [activeFrequencyFilter, setActiveFrequencyFilter] = useState<Frequency | 'Todas'>('Todas');
  const [isModalOpen, setIsModalOpen] = useState(false);

  const [editingItem, setEditingItem] = useState<Partial<ThirdPartyScheduleItem>>({});

  const handleAddNew = () => {
    setEditingItem({ 
        company: '', 
        service: '', 
        frequency: 'Mensal', 
        contact: '', 
        workStartDate: '', 
        workEndDate: '', 
        workNoticeDate: '' 
    });
    setIsModalOpen(true);
  };

  const handleEdit = (item: ThirdPartyScheduleItem) => {
      setEditingItem(item);
      setIsModalOpen(true);
  }

  const handleDelete = (id: string) => {
      if(window.confirm('Confirma a exclusão deste item do cronograma/obra?')) {
          deleteThirdPartyScheduleItem(id);
      }
  }

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = async (event) => {
          const content = event.target?.result as string;
          const result = await importDataFromCSV(content);
          alert(`${result.message}\n${result.count ? `Importados: ${result.count} registros.` : ''}`);
          e.target.value = ''; 
      };
      reader.readAsText(file);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    const payload = editingItem as ThirdPartyScheduleItem;

    if (!payload.company || !payload.service) { 
        alert("Informe Empresa e Serviço"); 
        return; 
    }

    if (payload.id) {
