                                />
                            </div>
                            <div>
                                <label className="block text-[10px] font-bold text-red-500 mb-1.5">AVISO PRÉVIO</label>
                                <input 
                                    type="date"
                                    value={editingItem.workNoticeDate || ''}
                                    onChange={e => setEditingItem({...editingItem, workNoticeDate: e.target.value})}
