          supabase.from('towers').select('*'),
          supabase.from('responsibles').select('*'),
          supabase.from('materials').select('*'),
          supabase.from('situations').select('*')
        ]);

        if (tasksRes.data) {
            setTasks(tasksRes.data.map((t: any) => ({
                id: String(t.id),
                title: t.title,
                sectorId: t.sector_id,
                serviceId: t.service_id,
