                startDate: t.start_date,
                endDate: t.end_date,
                description: t.description,
                createdAt: t.created_at
            })));
        }

        if (visitsRes.data) setVisits(visitsRes.data.map((v:any) => ({ ...v, id: String(v.id), returnDate: v.return_date })));
